require_once dirname(__DIR__).'/includes/bootstrap.php';require_role('Administrator');$pageTitle='System Settings';$activeMenu='settings';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$allowed=['company_name','company_address','fiscal_year_start','currency','receipt_required','budget_warning_threshold'];foreach($allowed as $k){$v=trim($_POST[$k]??'');db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_at=NOW()')->execute([$k,$v]);}log_activity('UPDATE','Settings','Updated system settings');flash('success','Settings saved.');redirect('settings/index.php');}$all=[];foreach(db()->query('SELECT setting_key,setting_value FROM settings')->fetchAll() as $x)$all[$x['setting_key']]=$x['setting_value'];require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>System Settings</h1><p>Core company and finance configuration for SMART BUDGET360.</p></div></div><div class="row"><div class="col-xl-8"><div class="card-panel"><div class="card-body"><form method="post"><?=csrf_field()?><div class="row g-3"><div class="col-md-6"><label class="form-label">Company Name</label><input class="form-control" name="company_name" value="<?=e($all['company_name']??'Your Company, Inc.')?>"></div><div class="col-md-6"><label class="form-label">Currency</label><select class="form-select" name="currency"><option value="PHP" <?=($all['currency']??'PHP')==='PHP'?'selected':''?>>PHP — Philippine Peso</option><option value="USD" <?=($all['currency']??'')==='USD'?'selected':''?>>USD — US Dollar</option></select></div><div class="col-12"><label class="form-label">Company Address</label><input class="form-control" name="company_address" value="<?=e($all['company_address']??'')?>"></div><div class="col-md-4"><label class="form-label">Fiscal Year Start</label><select class="form-select" name="fiscal_year_start"><?php for($m=1;$m<=12;$m++):?><option value="<?=$m?>" <?=((int)($all['fiscal_year_start']??1)===$m)?'selected':''?>><?=e(date('F',mktime(0,0,0,$m,1)))?></option><?php endfor;?></select></div><div class="col-md-4"><label class="form-label">Receipt Requirement</label><select class="form-select" name="receipt_required"><option value="optional" <?=($all['receipt_required']??'optional')==='optional'?'selected':''?>>Optional</option><option value="required" <?=($all['receipt_required']??'')==='required'?'selected':''?>>Required</option></select></div><div class="col-md-4"><label class="form-label">Budget Warning %</label><input class="form-control" type="number" min="1" max="100" name="budget_warning_threshold" value="<?=e($all['budget_warning_threshold']??'80')?>"></div><div class="col-12"><button class="btn btn-primary px-4">Save Settings</button></div></div></form></div></div></div><div class="col-xl-4 mt-3 mt-xl-0"><div class="info-banner"><strong>Security Configuration</strong><div class="small mt-2">Passwords use PHP password hashing. All application writes use prepared statements and CSRF tokens. Session cookies are HTTP-only with SameSite=Strict.</div></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
